    if ok and not empty and not dup:
        return {"sql": sql}

    # Draft failed, produced nothing, or repeats rows: gather evidence, repair once.
    evidence = "Your draft query:\n%s\n\nResult: %s" % (sql, _result_note(res))
    if dup:
        evidence += "\n\nRow-grain check: %s" % dup
    probes = _probe(env, schema, _literals(task)) if empty else ""
    if probes:
        evidence += "\n\nActual stored values found in this database:\n%s" % probes
    evidence += (
        "\n\nWrite a corrected query for the SAME question. Re-read the question and fix the real cause:"
        "\n- projection: if it asks WHICH entities / for an entity's details or records, return that entity's"
        " full row (`alias.*`) from its own table; if it names specific attributes, return exactly those;"
        "\n- filter scope: match text/values on the table that owns them (the paragraph/document/row itself,"
        " not a related table's name);"
        "\n- row grain: one row per asked-for entity (DISTINCT or EXISTS) when a relationship/enrolment join"
        " repeats it;"
        "\n- negation: for 'has no / never / without', exclude the entity from EVERY column that references it"
        " (both sides of a symmetric relationship table); an empty result usually means the exclusion or the"
        " filter value is wrong, not that the answer is empty;"
        "\n- values: use the exact stored spelling/case/encoding (flags may be 1/0 or 'T'/'F'; labels may be"
        " singular/plural or abbreviated)."
        "\nKeep whatever part of the draft was already correct. Return only one ```sql block."
    )
    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": evidence},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    try:
        res2 = env.execute(sql2, max_rows=20)
    except Exception:
        return {"sql": sql2}
    if not res2.get("ok"):
        return {"sql": sql}
    if empty and not (res2.get("rows") or []):
        return {"sql": sql}
    return {"sql": sql2}
